<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{fetchRuntimeInstances,type RuntimeEnvelope}from'./api';const state=ref<RuntimeEnvelope|null>(null),error=ref('');let timer:number|undefined;async function refresh(){try{state.value=await fetchRuntimeInstances();error.value=''}catch(e){error.value=String(e)}}const groups=computed(()=>{const m=new Map<string,RuntimeEnvelope['items']>();for(const i of state.value?.items??[]){const a=m.get(i.runtime_role)??[];a.push(i);m.set(i.runtime_role,a)}return[...m.entries()]});onMounted(async()=>{await refresh();timer=window.setInterval(refresh,10000)});onBeforeUnmount(()=>{if(timer)window.clearInterval(timer)})</script>
<template><section><h1>Batch Runtime Topology</h1><button @click="refresh">새로고침</button><p v-if="error" role="alert">{{error}}</p><p v-if="state?.partial||state?.stale"><strong>STALE/PARTIAL 상태입니다.</strong></p><article v-for="[role,items] in groups" :key="role"><h2>{{role}}</h2><table><thead><tr><th>Instance</th><th>Host</th><th>Version</th><th>Desired</th><th>Actual</th><th>Heartbeat</th><th>Fence</th></tr></thead><tbody><tr v-for="i in items" :key="i.instance_id"><td>{{i.instance_id}}</td><td>{{i.host_alias}}</td><td>{{i.artifact_version}}</td><td>{{i.desired_state}}</td><td>{{i.effective_state}}</td><td>{{i.last_heartbeat_at}}</td><td>{{i.fencing_token}}</td></tr></tbody></table></article></section></template>
